import android.content.res.AssetManager
import android.app.Application
import com.kobil.kssidp.wrapper.models.KssIdp
import com.kobil.kssidp.wrapper.models.KssIdpConfig
import com.kobil.wrapper.events.*

fun createStart(assets: AssetManager, mcConfigPath: String, sdkConfigPath: String,
    locale: String, version: AppVersion, appName: String, certificateChain: String,
    serverBackend: String): StartEvent {
    val mcConfig = assets.open(mcConfigPath).bufferedReader().use { it.readText() }
    val sdkConfig = assets.open(sdkConfigPath).use { it.readBytes() }
    require(mcConfig.isNotBlank() && sdkConfig.isNotEmpty()) { "Empty SDK assets" }
    return StartEvent(locale, version, appName, mcConfig, certificateChain, sdkConfig)
        .apply { this.serverBackend = serverBackend }
}
// Paths and serverBackend come from the selected delivery/configuration.
// Submit through the retained controller and inspect StartResultEvent.

fun configureIdp(application: Application, tenantId: String, baseUrl: String,
    certificatePath: String, wrapperHandlesTms: Boolean, hashPin: Boolean): KssIdp {
    KssIdp.init(application, KssIdpConfig(tenantId = tenantId, baseUrl = baseUrl,
        certificatePath = certificatePath, shouldKssIdpHandleTms = wrapperHandlesTms,
        shouldHashPin = hashPin))
    return checkNotNull(KssIdp.getInstance()) { "KSSIDP initialization failed" }
}
// Choose one TMS owner. Set wrapperHandlesTms from the app's chosen architecture,
// not an assumed universal default. Pass hashPin according to deployment policy.

