import Foundation
import KSMasterController
import kssidp

func createStart(serverBackend: String, appConfiguration: KSMSsmsAppConfiguration,
    mcConfigURL: URL, certificateURL: URL, iamCertificateURL: URL,
    configurationData: KSMConfigurationData) throws -> KSMStartEventEx {
    let mcConfig = try String(contentsOf: mcConfigURL, encoding: .utf8)
    let certificates = try Data(contentsOf: certificateURL)
    guard !mcConfig.isEmpty, !certificates.isEmpty else {
        throw NSError(domain: "SDKAssets", code: 1,
            userInfo: [NSLocalizedDescriptionKey: "Empty SDK assets"])
    }
    let iamCertificates = try Data(contentsOf: iamCertificateURL)
    guard !iamCertificates.isEmpty else { throw NSError(domain: "SDKAssets", code: 2) }
    let event = KSMStartEventEx(ssmsAppConfiguration: appConfiguration,
        mcConfig: mcConfig, certificateChain: certificates,
        configurationData: configurationData, iamCertificateChain: iamCertificates,
        smartScreenCertificateChain: Data())
    event.serverBackend = serverBackend
    return event
}
// Resolve URLs from the installed app bundle, not a developer machine path.
// Populate appConfiguration/configurationData from the selected release assets.

func configureIdp(tenantId: String, baseURL: String, certificatePath: String,
    controller: KSAsyncEventReceiver & KSEcoModulInterface & KSEventSource,
    wrapperHandlesTms: Bool, hashPin: Bool) throws -> KssIdpWrapper {
    try KssIdpWrapper(config: KssIdpConfig(certificatePath: certificatePath,
        baseUrl: baseURL, tenantId: tenantId, masterController: controller,
        shouldKssIdpHandleTms: wrapperHandlesTms, shouldHashPin: hashPin))
}
